  centre=[("S₂O₈²⁻ + 2I⁻ → 2SO₄²⁻ + I₂", "ion peroxodisulfate plus deux ions iodure"),
          ("Catalyseur : accélère, ne figure pas dans l'équation, même état final", "نعاود نقرا")],
